import contextlib
import io
import pathlib
import subprocess
import sys
import unittest

from textkit.cli import main
from textkit.rot import rot

ROOT = pathlib.Path(__file__).resolve().parent.parent


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RotFunctionTest(unittest.TestCase):
    def test_rot13_examples(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")
        self.assertEqual(rot("Uryyb, Jbeyq!", 13), "Hello, World!")

    def test_wraps_around_and_keeps_case(self):
        self.assertEqual(rot("xyzXYZ", 3), "abcABC")
        self.assertEqual(rot("abc", 26), "abc")

    def test_negative_and_large_n(self):
        self.assertEqual(rot("abc", -1), "zab")
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", -53), "bcd")

    def test_other_characters_unchanged(self):
        self.assertEqual(rot("1 2-3_é ?\n", 5), "1 2-3_é ?\n")

    def test_zero_is_identity(self):
        self.assertEqual(rot("Hello", 0), "Hello")

    def test_non_int_n_raises(self):
        for bad in [1.5, "13", True, False, None]:
            with self.subTest(n=bad):
                with self.assertRaises(ValueError):
                    rot("abc", bad)


class RotCommandTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(run("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_n_option(self):
        self.assertEqual(run("rot", "abc", "--n", "-1"), (0, "zab\n", ""))

    def test_non_int_n_is_error(self):
        code, out, err = run("rot", "abc", "--n", "1.5")
        self.assertEqual((code, out), (2, ""))
        self.assertEqual(err, "error: n must be an integer: '1.5'\n")

    def test_json_wraps_output(self):
        code, out, _ = run("--json", "rot", "abc", "--n", "1")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["bcd"]', out)

    def test_subprocess_examples(self):
        def cli(*args):
            return subprocess.run(
                [sys.executable, "-m", "textkit", *args],
                cwd=ROOT, capture_output=True, text=True,
            )

        p = cli("rot", "Hello, World!")
        self.assertEqual((p.returncode, p.stdout), (0, "Uryyb, Jbeyq!\n"))

        p = cli("rot", "abc", "--n", "-1")
        self.assertEqual((p.returncode, p.stdout), (0, "zab\n"))

        p = cli("rot", "abc", "--n", "1.5")
        self.assertEqual(p.returncode, 2)
        self.assertIn("error:", p.stderr)


if __name__ == "__main__":
    unittest.main()

